import os, re, subprocess
from collections import defaultdict

REPO = "/bench/repo"
DATA_LAYER_PREFIXES = ("store/", "proto/store/", "proto/gen/store/")

def is_data_layer(path):
    rel = path[len(REPO)+1:]
    return rel.startswith(DATA_LAYER_PREFIXES)

def get_package(path):
    rel = path[len(REPO)+1:]
    return os.path.dirname(rel)

# Persistent entity types (DB-mapped structs in store/)
ENTITIES = [
    "User", "Memo", "Attachment", "IdentityProvider", "Inbox",
    "InstanceSetting", "MemoRelation", "MemoShare", "Reaction",
    "UserIdentity", "UserSetting",
]

# Also proto payload types in data layer
PROTO_ENTITIES = [
    "MemoPayload", "AttachmentPayload", "IdentitySetting", "IdentityProviderConfig",
    "InboxMessage", "InstanceSetting", "InstanceSettingKey", "UserSetting",
    "GeneralUserSetting", "OAuth2Config",
]

def find_go_files():
    result = subprocess.run(["find", REPO, "-name", "*.go"], capture_output=True, text=True)
    files = result.stdout.strip().split('\n')
    return [f for f in files if f and not is_data_layer(f)]

def count_refs(patterns, files_content):
    pkg_refs = defaultdict(set)  # entity -> set of packages
    file_refs = defaultdict(set)  # entity -> set of files

    for fpath, content in files_content.items():
        pkg = get_package(fpath)
        for entity, patterns_list in patterns.items():
            for pat in patterns_list:
                if re.search(pat, content):
                    pkg_refs[entity].add(pkg)
                    file_refs[entity].add(fpath[len(REPO)+1:])
                    break
    return pkg_refs, file_refs

# Build patterns for each entity
patterns = {}
for e in ENTITIES:
    patterns[e] = [
        rf'\bstore\.{e}\b',
        rf'\bstore\.Find{e}\b',
        rf'\bstore\.Update{e}\b',
        rf'\bstore\.Delete{e}\b',
    ]
for e in PROTO_ENTITIES:
    patterns[f"{e} (proto)"] = [rf'\bstorepb\.{e}\b']

files_content = {}
for f in find_go_files():
    with open(f) as fh:
        files_content[f] = fh.read()

pkg_refs, file_refs = count_refs(patterns, files_content)

print("=== Reference counts (distinct packages outside data layer) ===\n")
results = sorted(pkg_refs.items(), key=lambda x: -len(x[1]))
for entity, pkgs in results:
    print(f"{entity}: {len(pkgs)} packages")
    for p in sorted(pkgs):
        print(f"  - {p}")
    print()

print("\n=== TOP RANKING ===")
for i, (entity, pkgs) in enumerate(results[:5], 1):
    print(f"{i}. {entity}: ~{len(pkgs)} packages")
PYEOF

