perl -e '
use strict; use warnings;
my $REPO = "/bench/repo";
my @ENTITIES = qw(User Memo Attachment IdentityProvider Inbox InstanceSetting MemoRelation MemoShare Reaction UserIdentity UserSetting);
my @PROTO = qw(MemoPayload AttachmentPayload IdentityProviderConfig InboxMessage InstanceSetting InstanceSettingKey UserSetting GeneralUserSetting OAuth2Config);

sub is_data_layer {
    my ($f) = @_;
    $f =~ s/^\Q$REPO\E\///;
    return 1 if $f =~ /^store\// || $f =~ /^proto\/store\// || $f =~ /^proto\/gen\/store\//;
    return 0;
}

sub get_pkg {
    my ($f) = @_;
    $f =~ s/^\Q$REPO\E\///;
    (my $d = $f) =~ s/\/[^\/]+$//;
    return $d;
}

my %patterns;
for my $e (@ENTITIES) {
    $patterns{$e} = [qr/\bstore\.$e\b/, qr/\bstore\.Find$e\b/, qr/\bstore\.Update$e\b/, qr/\bstore\.Delete$e\b/];
}
for my $e (@PROTO) {
    $patterns{"$e (proto)"} = [qr/\bstorepb\.$e\b/];
}

my %pkg_refs;
my %file_refs;

opendir(my $dh, $REPO) or die;
my @files;
sub walk {
    my ($dir) = @_;
    opendir(my $d, $dir) or return;
    while (my $e = readdir $d) {
        next if $e =~ /^\./;
        my $p = "$dir/$e";
        if (-d $p) { walk($p); }
        elsif ($p =~ /\.go$/) { push @files, $p unless is_data_layer($p); }
    }
}
walk($REPO);

for my $f (@files) {
    open my $fh, "<", $f or next;
    local $/; my $content = <$fh>; close $fh;
    my $pkg = get_pkg($f);
    for my $entity (keys %patterns) {
        for my $pat (@{$patterns{$entity}}) {
            if ($content =~ /$pat/) {
                $pkg_refs{$entity}{$pkg} = 1;
                $file_refs{$entity}{$f} = 1;
                last;
            }
        }
    }
}

print "=== Reference counts (distinct packages outside data layer) ===\n\n";
my @sorted = sort { scalar(keys %{$pkg_refs{$b}}) <=> scalar(keys %{$pkg_refs{$a}}) } keys %pkg_refs;
for my $entity (@sorted) {
    my @pkgs = sort keys %{$pkg_refs{$entity}};
    print "$entity: ", scalar(@pkgs), " packages\n";
    print "  - $_\n" for @pkgs;
    print "\n";
}

print "=== TOP 5 ===\n";
for my $i (0..4) {
    last unless $sorted[$i];
    my $e = $sorted[$i];
    my $n = scalar keys %{$pkg_refs{$e}};
    print ($i+1).". $e: ~$n packages\n";
}
'

