python3 << 'PYEOF'
import os, re
from collections import defaultdict

ROOT = "/bench/repo"
DATA_LAYER_PREFIXES = ("store/", "proto/store/", "proto/gen/store/")

# Find entity types in store/*.go (top level only, not db/)
entities = []
store_dir = os.path.join(ROOT, "store")
for fn in sorted(os.listdir(store_dir)):
    if not fn.endswith(".go") or fn.endswith("_test.go"):
        continue
    path = os.path.join(store_dir, fn)
    with open(path) as f:
        for line in f:
            m = re.match(r'^type (\w+) struct', line)
            if m:
                entities.append((m.group(1), f"store/{fn}"))

print("Entities:")
for e, f in entities:
    print(f"  {e} ({f})")

# Count package references outside data layer
def package_of(relpath):
    parts = relpath.split("/")
    if parts[0] == "server" and len(parts) >= 3:
        return "/".join(parts[:3])
    if parts[0] == "plugin" and len(parts) >= 2:
        return "/".join(parts[:2])
    return parts[0]

def is_outside_data_layer(relpath):
    return not any(relpath.startswith(p) for p in DATA_LAYER_PREFIXES)

counts = {}
for entity, _ in entities:
    pattern = re.compile(r'\bstore\.' + re.escape(entity) + r'\b')
    pkgs = set()
    for dirpath, _, files in os.walk(ROOT):
        for fn in files:
            if not fn.endswith(".go"):
                continue
            full = os.path.join(dirpath, fn)
            rel = os.path.relpath(full, ROOT)
            if not is_outside_data_layer(rel):
                continue
            try:
                with open(full) as f:
                    if pattern.search(f.read()):
                        pkgs.add(package_of(rel))
            except Exception:
                pass
    counts[entity] = sorted(pkgs)

print("\nReference counts (outside data layer):")
for entity, _ in sorted(entities, key=lambda x: -len(counts[x[0]])):
    pkgs = counts[entity]
    print(f"  {entity}: {len(pkgs)} packages -> {pkgs}")
